class DanmakuToggleIcon extends StatelessWidget {
  final bool enabled;
  final double size;
  final Color primaryColor;
  final Color enabledAccentColor;
  final Color disabledAccentColor;

  const DanmakuToggleIcon({
    super.key,
    required this.enabled,
    this.size = 24,
    this.primaryColor = Colors.white,
    this.enabledAccentColor = const Color(0xFF35C759),
    this.disabledAccentColor = const Color(0xFFFF5A5F),
  });

  @override
  Widget build(BuildContext context) {
    return SvgPicture.string(
      enabled
          ? _buildToggleOnSvg(
              primaryColor: primaryColor,
              accentColor: enabledAccentColor,
            )
          : _buildToggleOffSvg(
              primaryColor: primaryColor,
              accentColor: disabledAccentColor,
            ),
      width: size,
      height: size,
    );
  }
}

